package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.*;
import dev.starfold.PlanetSpace.Side;
import java.util.*;
import java.util.function.Consumer;

/** Complete cached six-face fallback, not an independently painted planet.
 * Untouched flat tiles are merged; every edited tile and its neighbours retain exact exposed faces.
 * A tile is replaced only after its complete fine VBO is resident. */
public final class GroundCover {
    public record Quad(Cell owner,Side side,int material,Point a,Point b,Point c,Point d){public Point vertex(int i){return switch(i){case 0->a;case 1->b;case 2->c;default->d;};}}
    public static void face(GroundWorld w,Face face,Consumer<Quad> out){
        for(int v=0;v<GroundSpace.SIZE;v+=16)for(int u=0;u<GroundSpace.SIZE;u+=16){
            int tile=GroundSpace.tile(new Cell(face,u,0,v));
            if(w.detailed(tile)){for(var q:w.mesh(tile))out.accept(new Quad(q.owner(),q.side(),q.material(),q.vertex(0),q.vertex(1),q.vertex(2),q.vertex(3)));extension(w,tile,out);continue;}
            var xs=cuts(u,w.config().core());var zs=cuts(v,w.config().core());
            for(int x=0;x<xs.length-1;x++)for(int z=0;z<zs.length-1;z++){
                int a=xs[x],b=xs[x+1],c=zs[z],d=zs[z+1];var owner=new Cell(face,a,-1,c);boolean mask=GroundSpace.column(w.config(),owner);int h=mask?w.config().height():0,m=mask?1:22;
                out.accept(new Quad(new Cell(face,a,h-1,c),Side.UP,m,new Point(a,h,c),new Point(a,h,d),new Point(b,h,d),new Point(b,h,c)));
                if(!mask)continue;
                if(!GroundSpace.column(w.config(),w.neighbor(owner,Side.WEST)))wall(out,owner,Side.WEST,a,c,a,d,h);
                if(!GroundSpace.column(w.config(),w.neighbor(new Cell(face,b-1,0,c),Side.EAST)))wall(out,owner,Side.EAST,b,d,b,c,h);
                if(!GroundSpace.column(w.config(),w.neighbor(owner,Side.NORTH)))wall(out,owner,Side.NORTH,b,c,a,c,h);
                if(!GroundSpace.column(w.config(),w.neighbor(new Cell(face,a,0,d-1),Side.SOUTH)))wall(out,owner,Side.SOUTH,a,d,b,d,h);
            }
        }
    }
    /** Add the same physical overlay above stored blocks to BOTH fine and edited fallback
     * tiles. No extra block keys, per-height allocation or duplicate stored-layer surfaces. */
    public static void extension(GroundWorld w,int tile,Consumer<Quad> out){
        int h=w.config().height();if(h<=GroundSpace.MAX)return;
        int u=tile%GroundSpace.ACROSS*GroundSpace.TILE,v=tile/GroundSpace.ACROSS%GroundSpace.ACROSS*GroundSpace.TILE;
        var face=Face.values()[tile/(GroundSpace.ACROSS*GroundSpace.ACROSS)];var xs=cuts(u,w.config().core());var zs=cuts(v,w.config().core());
        for(int x=0;x<xs.length-1;x++)for(int z=0;z<zs.length-1;z++){
            int a=xs[x],b=xs[x+1],c=zs[z],d=zs[z+1];var owner=new Cell(face,a,GroundSpace.MAX,c);if(!GroundSpace.column(w.config(),owner))continue;
            out.accept(new Quad(new Cell(face,a,h-1,c),Side.UP,1,new Point(a,h,c),new Point(a,h,d),new Point(b,h,d),new Point(b,h,c)));
            if(!GroundSpace.column(w.config(),w.neighbor(owner,Side.WEST)))wall(out,owner,Side.WEST,a,c,a,d,GroundSpace.MAX,h);
            if(!GroundSpace.column(w.config(),w.neighbor(new Cell(face,b-1,0,c),Side.EAST)))wall(out,owner,Side.EAST,b,d,b,c,GroundSpace.MAX,h);
            if(!GroundSpace.column(w.config(),w.neighbor(owner,Side.NORTH)))wall(out,owner,Side.NORTH,b,c,a,c,GroundSpace.MAX,h);
            if(!GroundSpace.column(w.config(),w.neighbor(new Cell(face,a,0,d-1),Side.SOUTH)))wall(out,owner,Side.SOUTH,a,d,b,d,GroundSpace.MAX,h);
        }
    }
    private static int[] cuts(int lo,int core){return java.util.stream.IntStream.of(lo,lo+16,core,GroundSpace.SIZE-core).filter(i->i>=lo&&i<=lo+16).distinct().sorted().toArray();}
    private static void wall(Consumer<Quad> out,Cell owner,Side side,int a,int c,int b,int d,int h){wall(out,owner,side,a,c,b,d,0,h);}
    private static void wall(Consumer<Quad> out,Cell owner,Side side,int a,int c,int b,int d,int low,int h){
        // Logarithmic segments keep extreme heights bounded in work and avoid one giant
        // triangle joining the near ground to coordinates billions of blocks away.
        for(int y=low;y<h;){int next=(int)Math.min((long)h,y<GroundSpace.MAX?GroundSpace.MAX:Math.max(128L,2L*y));out.accept(new Quad(owner,side,1,new Point(a,y,c),new Point(b,y,d),new Point(b,next,d),new Point(a,next,c)));y=next;}
    }
    private GroundCover(){}
}

